contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback(bytes calldata) external payable returns (bytes memory) {
        return new bytes(32);
    }

    function run(uint256 artId, uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.initialize(1, 2, "vt", address(this));
        uint256 before = c.tokenIdCounter();
        uint256 t = c.createArtFromFactory{value: amount}(artId);
        assert(
            t == before
            && c.getTokenIdFromFactoryArtId(artId) == t
            && c.getFactoryArtId(t) == artId
            && c.tokenIdCounter() == before + 1
        );
    }

    receive() external payable {}
}

