contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        c.initialize(1, 2, "vt", address(this));
        c.pause();
        bool p1 = c.paused();
        c.unPause();
        assert(p1 == true && c.paused() == false && c.owner() == address(this));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 chainId, uint256 credId, string memory vt, address feeDest) public payable {
        c.initialize(chainId, credId, vt, feeDest);
        bool reverted;
        try c.initialize(chainId + 1, credId + 1, vt, feeDest) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == address(this) && c.credChainId() == chainId && c.credId() == credId);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 credChainId_, uint256 credId_, string memory verificationType_, address protocolFeeDestination_) public {
        c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_);
        bool pausedBefore = c.paused();
        c.pause();
        bool pausedAfter = c.paused();
        bool secondPauseReverted;
        try c.pause() { secondPauseReverted = false; } catch { secondPauseReverted = true; }
        c.unPause();
        bool pausedEnd = c.paused();
        assert(!pausedBefore && pausedAfter && secondPauseReverted && !pausedEnd);
    }
    receive() external payable {}
}

