contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account, uint256 id) public {
        require(account != address(0));
        require(id < 1e24);
        assert(
            c.balanceOf(account, id) == 0
            && c.totalSupply(id) == 0
            && c.totalSupply() == 0
            && !c.exists(id)
            && !c.isApprovedForAll(account, address(this))
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        require(newOwner != address(0) && newOwner != address(this));
        c.initialize(1, 2, "v", address(this));
        c.transferOwnership(newOwner);
        assert(c.pendingOwner() == newOwner && c.owner() == address(this));
    }
    receive() external payable {}
    fallback() external payable {
        assembly {
            mstore(0, 0x01)
            return(0, 32)
        }
    }
}

